window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ee384a62df020ca6"]={"versions": [{"id": "FIG-ee384a62df020ca6", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Feature-Baum / Feature-Diagramm (FODA-basiertes Variabilitätsmodell) mit transversalen logischen Restriktionen (<em>Cross-Tree Constraints</em>).\n</li><li><strong>Architektur-Kontext &amp; Zweck:</strong> AUTOSAR Foundation (FO), Spezifikation <code>AUTOSAR_FO_RS_FeatureModelExchangeFormat</code> (<code>UC_FMDT_00004</code>). Dient der werkzeugunabhängigen Modellierung und dem Austausch von Produktlinien-Variabilität (Software Product Line Engineering – SPLE) auf OEM-/Tier-1-Systemebene.\n</li><li><strong>Funktionale Einordnung:</strong> Entkoppelt orthogonale Feature-Dimensionen (z. B. Zielland vs. physische Lenkung vs. Kombiinstrument-Einheiten), um eine kombinatorische Explosion und Redundanz in der Baumhierarchie zu verhindern. Abhängigkeiten werden über separate aussagenlogische Restriktionen aufgelöst.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelknoten (Root Feature):</strong>\n<ul class=\"fig-list\"><li><code>Feature Model: Sample Car</code> (Top-Level-Systementität).\n</li></ul>\n</li><li><strong>Pflicht-Feature-Gruppen (<code>Mandatory</code>, Multiplizität [1..1] bezüglich Parent):</strong>\n<ul class=\"fig-list\"><li><code>Mandatory: Country</code> (Zielmarkt).\n</li><li><code>Mandatory: Steering Wheel</code> (Lenkradposition).\n</li><li><code>Mandatory: Speedometer display</code> (Tachoanzeigeeinheit).\n</li></ul>\n</li><li><strong>Kind-Features in XOR-Gruppen (<code>Alternative</code>, Multiplizität exakt 1 aus N selektierbar):</strong>\n<ul class=\"fig-list\"><li>Unter <code>Country</code>: <code>Alternative: Germany</code>, <code>Alternative: UK</code>, <code>Alternative: US</code>.\n</li><li>Unter <code>Steering Wheel</code>: <code>Alternative: Left</code> (LHD), <code>Alternative: Right</code> (RHD).\n</li><li>Unter <code>Speedometer display</code>: <code>Alternative: km/h</code>, <code>Alternative: mph</code>.\n</li></ul>\n</li><li><strong>Transversale Restriktionen (Cross-Tree Constraints / Notiz-Elemente via gestrichelter Kanten):</strong>\n<ul class=\"fig-list\"><li>C_1: $\\text{Left} \\implies (\\text{Germany} \\lor \\text{US})$\n</li><li>C_2: $\\text{Right} \\implies \\text{UK}$\n</li><li>C_3: $\\text{km/h} \\implies \\text{Germany}$\n</li><li>C_4: $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Modellierungsartefakt:</strong> Kein Laufzeit-Sequenzablauf (keine RTE-/BSW-Tasks, keine PDUs, keine Callbacks).\n</li><li><strong>Konfigurations- &amp; Auflösungsprozess (Design-/Build-Time):</strong>\n<ul class=\"fig-list\"><li><strong>Constraint-Satisfaction-Problem (CSP / SAT):</strong> Werkzeuge zur Variantenkonfiguration übergeben den Feature-Baum samt Restriktionsmatrix an einen SAT-Solver.\n</li><li><strong>Auswertungssequenz:</strong>\n<ol class=\"fig-list\"><li>Bindung des Primärparameters (z. B. Selektion <code>Country == Germany</code>).\n</li><li>Propagation der Constraints: Germany forciert Steering Wheel = Left (da $\\text{Right} \\implies \\text{UK}$) und Speedometer display = km/h (da $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$ und Auswahl von km/h mit Germany konsistent ist).\n</li><li>Eine inkonsistente Selektion (z. B. <code>Germany</code> + <code>Right</code>) verletzt C_2 und führt zum Abbruch der Konfigurationsgenerierung (<em>Unfeasible Configuration Error</em>).\n</li></ol>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>**Bindungszeitpunkt (<em>Variation Binding Time</em>):** Primär <code>System Definition Time</code> bzw. <code>Pre-Compile Time</code>. \n</li><li><strong>Abbildung auf Classic/Adaptive AUTOSAR-Artefakte:</strong>\n<ul class=\"fig-list\"><li>Das FMDT dient als vorgelagertes Modell für das <code>AUTOSAR_TPS_SystemTemplate</code>.\n</li><li>Ausgewählte Features mappen direkt auf <code>VariationPoint</code>-Elemente in System Description, Software Component Description (SWCD) und BSW-Konfiguration (<code>EcucValueCollection</code>).\n</li><li>Steuert bedingte Kompilierung (<code>#ifdef</code> via <code>Pre-Compile Time</code> Variation Switches) sowie die selektive Generierung von Runnables, Ports oder RTE-APIs.\n</li></ul>\n</li><li><strong>Architektur-Richtlinie für Entwickler:</strong>\n<ul class=\"fig-list\"><li>Variabilitäten niemals durch kaskadierte Sub-Bäume je Ländermarkt duplizieren.\n</li><li>Orthogonale Domänen sauber trennen; Querverbindungen ausschließlich als minimale aussagenlogische Klauseln (<em>Requires</em> / <em>Excludes</em> bzw. Boole&#x27;sche Terme) im Feature-Modell definieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5d270a1504464274", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Feature-Baum / Feature-Diagramm (FODA-basiertes Variabilitätsmodell) mit transversalen logischen Restriktionen (<em>Cross-Tree Constraints</em>).\n</li><li><strong>Architektur-Kontext &amp; Zweck:</strong> AUTOSAR Foundation (FO), Spezifikation <code>AUTOSAR_FO_RS_FeatureModelExchangeFormat</code> (<code>UC_FMDT_00004</code>). Dient der werkzeugunabhängigen Modellierung und dem Austausch von Produktlinien-Variabilität (Software Product Line Engineering – SPLE) auf OEM-/Tier-1-Systemebene.\n</li><li><strong>Funktionale Einordnung:</strong> Entkoppelt orthogonale Feature-Dimensionen (z. B. Zielland vs. physische Lenkung vs. Kombiinstrument-Einheiten), um eine kombinatorische Explosion und Redundanz in der Baumhierarchie zu verhindern. Abhängigkeiten werden über separate aussagenlogische Restriktionen aufgelöst.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelknoten (Root Feature):</strong>\n<ul class=\"fig-list\"><li><code>Feature Model: Sample Car</code> (Top-Level-Systementität).\n</li></ul>\n</li><li><strong>Pflicht-Feature-Gruppen (<code>Mandatory</code>, Multiplizität [1..1] bezüglich Parent):</strong>\n<ul class=\"fig-list\"><li><code>Mandatory: Country</code> (Zielmarkt).\n</li><li><code>Mandatory: Steering Wheel</code> (Lenkradposition).\n</li><li><code>Mandatory: Speedometer display</code> (Tachoanzeigeeinheit).\n</li></ul>\n</li><li><strong>Kind-Features in XOR-Gruppen (<code>Alternative</code>, Multiplizität exakt 1 aus N selektierbar):</strong>\n<ul class=\"fig-list\"><li>Unter <code>Country</code>: <code>Alternative: Germany</code>, <code>Alternative: UK</code>, <code>Alternative: US</code>.\n</li><li>Unter <code>Steering Wheel</code>: <code>Alternative: Left</code> (LHD), <code>Alternative: Right</code> (RHD).\n</li><li>Unter <code>Speedometer display</code>: <code>Alternative: km/h</code>, <code>Alternative: mph</code>.\n</li></ul>\n</li><li><strong>Transversale Restriktionen (Cross-Tree Constraints / Notiz-Elemente via gestrichelter Kanten):</strong>\n<ul class=\"fig-list\"><li>C_1: $\\text{Left} \\implies (\\text{Germany} \\lor \\text{US})$\n</li><li>C_2: $\\text{Right} \\implies \\text{UK}$\n</li><li>C_3: $\\text{km/h} \\implies \\text{Germany}$\n</li><li>C_4: $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Modellierungsartefakt:</strong> Kein Laufzeit-Sequenzablauf (keine RTE-/BSW-Tasks, keine PDUs, keine Callbacks).\n</li><li><strong>Konfigurations- &amp; Auflösungsprozess (Design-/Build-Time):</strong>\n<ul class=\"fig-list\"><li><strong>Constraint-Satisfaction-Problem (CSP / SAT):</strong> Werkzeuge zur Variantenkonfiguration übergeben den Feature-Baum samt Restriktionsmatrix an einen SAT-Solver.\n</li><li><strong>Auswertungssequenz:</strong>\n<ol class=\"fig-list\"><li>Bindung des Primärparameters (z. B. Selektion <code>Country == Germany</code>).\n</li><li>Propagation der Constraints: Germany forciert Steering Wheel = Left (da $\\text{Right} \\implies \\text{UK}$) und Speedometer display = km/h (da $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$ und Auswahl von km/h mit Germany konsistent ist).\n</li><li>Eine inkonsistente Selektion (z. B. <code>Germany</code> + <code>Right</code>) verletzt C_2 und führt zum Abbruch der Konfigurationsgenerierung (<em>Unfeasible Configuration Error</em>).\n</li></ol>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>**Bindungszeitpunkt (<em>Variation Binding Time</em>):** Primär <code>System Definition Time</code> bzw. <code>Pre-Compile Time</code>. \n</li><li><strong>Abbildung auf Classic/Adaptive AUTOSAR-Artefakte:</strong>\n<ul class=\"fig-list\"><li>Das FMDT dient als vorgelagertes Modell für das <code>AUTOSAR_TPS_SystemTemplate</code>.\n</li><li>Ausgewählte Features mappen direkt auf <code>VariationPoint</code>-Elemente in System Description, Software Component Description (SWCD) und BSW-Konfiguration (<code>EcucValueCollection</code>).\n</li><li>Steuert bedingte Kompilierung (<code>#ifdef</code> via <code>Pre-Compile Time</code> Variation Switches) sowie die selektive Generierung von Runnables, Ports oder RTE-APIs.\n</li></ul>\n</li><li><strong>Architektur-Richtlinie für Entwickler:</strong>\n<ul class=\"fig-list\"><li>Variabilitäten niemals durch kaskadierte Sub-Bäume je Ländermarkt duplizieren.\n</li><li>Orthogonale Domänen sauber trennen; Querverbindungen ausschließlich als minimale aussagenlogische Klauseln (<em>Requires</em> / <em>Excludes</em> bzw. Boole&#x27;sche Terme) im Feature-Modell definieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ee384a62df020ca6", "to": "FIG-5d270a1504464274", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
